const responseHeaders = {
  'Cache-Control': 'private, no-store, max-age=0',
  'Referrer-Policy': 'no-referrer',
  'X-Content-Type-Options': 'nosniff'
};

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {status, headers: {...responseHeaders, 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*'}});
}

function sourceConfig(env) {
  try {
    const source = new URL(env.SUPABASE_URL);
    if (source.protocol !== 'https:' || !/^[a-z0-9-]+\.supabase\.co$/.test(source.hostname) || source.username || source.password || source.port || source.search || source.hash || source.pathname !== '/' || !env.SUPABASE_ANON_KEY) return null;
    return {url: source.origin, key: env.SUPABASE_ANON_KEY, sourceId: source.hostname + '/luckyjet_classic_history'};
  } catch {return null;}
}

async function rounds(request, env) {
  const params = new URL(request.url).searchParams;
  const rawLimit = params.get('limit') ?? '2000', after = params.get('after');
  const limit = Number(rawLimit);
  if (!/^\d+$/.test(rawLimit) || !Number.isInteger(limit) || limit < 20 || limit > 2000 || (after !== null && (!/^\d+$/.test(after) || !Number.isSafeInteger(Number(after))))) return json({error: 'Некорректные параметры истории.'}, 400);
  const config = sourceConfig(env);
  if (!config) return json({error: 'Подключение Supabase не настроено.'}, 503);
  const controller = new AbortController(), timeout = setTimeout(() => controller.abort(), 10000);
  try {
    const rows = [];
    let cursor = after;
    while (rows.length < limit) {
      const pageSize = Math.min(1000, limit - rows.length);
      const query = new URLSearchParams({select: 'id,coefficient,round_timestamp,estimated,feed_order', order: after === null ? 'feed_order.desc' : 'feed_order.asc', limit: String(pageSize), offset: '0'});
      if (cursor !== null) query.set('feed_order', (after === null ? 'lt.' : 'gt.') + cursor);
      const result = await fetch(config.url + '/rest/v1/luckyjet_classic_history?' + query, {method: 'GET', headers: {apikey: config.key, Authorization: 'Bearer ' + config.key, Accept: 'application/json', 'Cache-Control': 'no-cache', Pragma: 'no-cache'}, redirect: 'manual', signal: controller.signal});
      if (!result.ok) return json({error: 'Источник Supabase временно недоступен.'}, result.status === 429 ? 429 : 502);
      const batch = await result.json();
      if (!Array.isArray(batch) || batch.some(row => !row || typeof row !== 'object' || Array.isArray(row))) return json({error: 'Источник вернул некорректную историю.'}, 502);
      rows.push(...batch.slice(0, pageSize).map(row => ({id: row.id, coefficient: row.coefficient, round_timestamp: row.round_timestamp, estimated: row.estimated, feed_order: row.feed_order})));
      if (batch.length < pageSize) break;
      const nextCursor = batch[Math.min(batch.length, pageSize) - 1]?.feed_order;
      if (!Number.isSafeInteger(nextCursor) || (cursor !== null && (after === null ? nextCursor >= Number(cursor) : nextCursor <= Number(cursor)))) return json({error: 'Источник вернул некорректный порядок истории.'}, 502);
      cursor = String(nextCursor);
    }
    return json({source: 'supabase', rounds: rows, servedAt: new Date().toISOString(), gameOrderVerified: false});
  } catch (error) {
    const message = String(error?.message || 'Unknown error').replaceAll(config.key, '[redacted]').slice(0, 240);
    console.error('Supabase history fetch failed:', error?.name || 'Error', message);
    return json({error: 'Не удалось получить историю Supabase. Повторите запрос.'}, 502);
  } finally {clearTimeout(timeout);}
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/api/rounds') {
      if (!['GET', 'HEAD'].includes(request.method)) return new Response('Method not allowed', {status: 405, headers: {...responseHeaders, Allow: 'GET, HEAD'}});
      const result = await rounds(request, env);
      return request.method === 'HEAD' ? new Response(null, {status: result.status, headers: result.headers}) : result;
    }
    if (!['/', '/index.html'].includes(url.pathname)) return new Response('Not found', {status: 404});
    if (!['GET', 'HEAD'].includes(request.method)) return new Response('Method not allowed', {status: 405, headers: {Allow: 'GET, HEAD'}});
    const source = sourceConfig(env);
    const config = JSON.stringify({url: '/api/rounds', configured: !!source, sourceId: source?.sourceId || ''}).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
    const html = page.replace('/*__HOSTED_CLOUD__*/null', config);
    return new Response(request.method === 'HEAD' ? null : html, {headers: {
      'Content-Type': 'text/html; charset=utf-8',
      ...responseHeaders
    }});
  }
};
